<template>
    <div class="mb-3">
        <div class="row item1 p-1 mb-2" v-for="(item, index) in formData.ConstraintStudentsSetMinHoursDaily">
            <div class="col-4">
                <label class="form-label">Apprenants:</label>
                <select class="form-select" v-model="item.Students">
                    <option value="" disabled>Sélectionnez un groupe</option>
                    <option v-for="student in formData.students.filter(student => student.name !== '')" :value="student.name">{{ student.name }}</option>
                </select>
            </div>
            <div class="col-3">
                <label class="form-label">Heures quotidiennes minimales :</label>
                <input type="number" min="0" class="form-control" v-model="item.Minimum_Hours_Daily">
            </div>
            <div class="col-3">
                <label class="form-label"><input type="checkbox" v-model="item.Allow_Empty_Days"> Autoriser jours vides</label>
            </div>
            <div class="col-2 mt-4">
                <button type="button" class="btn btn-danger btn-sm" @click="removeConstraint(index)">
                    <i class="fas fa-trash me-1"></i>Supprimer
                </button>
            </div>
        </div>
        <button type="button" class="btn btn-primary btn-add" @click="addConstraint">
            <i class="fas fa-plus me-1"></i>Ajouter
        </button>
    </div>
</template>

<script>
export default {
    name: 'ConstraintStudentsSetMinHoursDaily',
    props: {
        formData: {
            type: Object,
            required: true
        }
    },
    methods: {
        addConstraint() {
            this.formData.ConstraintStudentsSetMinHoursDaily.push({
                Students: '',
                Minimum_Hours_Daily: 1,
                Allow_Empty_Days: false
            });
        },
        removeConstraint(index) {
            this.formData.ConstraintStudentsSetMinHoursDaily.splice(index, 1);
        }
    }
}
</script>

<style scoped>
    .item1{
        border: 1px solid #dee2e6;
        border-radius: 0.25rem;
        background-color: #f8f9fa;
    }
</style>